    static final String ITEM="11111111111111111111111111111111",USER="22222222222222222222222222222222",LIBRARY="33333333333333333333333333333333";
    static JSONObject jfItem()throws Exception{return new JSONObject().put("Id",ITEM).put("Type","Movie").put("Name","Arrival · Demo").put("DateCreated","2026-01-01T00:00:00Z").put("ProviderIds",new JSONObject().put("Tmdb","329865")).put("ImageTags",new JSONObject().put("Primary","fixture")).put("UserData",new JSONObject().put("Played",false));}
